$a = [self:read]{path:"inputs_transfer/assets.json"}.data.items
$c = [self:read]{path:"inputs_transfer/checks.json"}.data.items
$v = [self:read]{path:"inputs_transfer/invoices.json"}.data.items
$odd = $v >> [table:filter]{where:($r)=> not (has($r,"machine") and has($r,"fee") and not has($r,"amount") and not has($r,"asset_id"))}
$fees = unique($v >> [table:filter]{where:($r)=>has($r,"fee")} >> [table:each]{return replace(replace(text($it.fee), ",", ""), "0","")[0:5]})
$ids = $v >> [table:each]{return get($it,"invoice_id")}
return {na:len($a), nc:len($c), nv:len($v), nuniq_ids:len(unique($ids)), odd:$odd, fee_prefix:$fees,
  akeys:unique($a >> [table:each]{return json(keys($it))}), ckeys:unique($c >> [table:each]{return json($it)[0:0] + json(keys($it)) + json(get($it,"checked"))}),
  aid_uniq:len(unique($a >> [table:each]{return $it.asset_id})), ccount_uniq:len(unique($c >> [table:each]{return get($it,"asset_id")}))}

$a = [self:read]{path:"inputs_transfer/assets.json"}.data.items
$c = [self:read]{path:"inputs_transfer/checks.json"}.data.items
$v = [self:read]{path:"inputs_transfer/invoices.json"}.data.items
$r = [fn:장비점검청구대사]{장비:$a, 점검:$c, 청구:$v, 허용차:500}
$br = sorted(unique($r.rows >> [table:each]{return $it.branch}))
$bt = $br >> [table:each] {
  $b = $it
  return {branch:$b, actual_cost:sum($r.rows >> [table:filter]{where:($x)=> $x.branch == $b} >> [table:each]{return $it.actual_cost})}
}
$out = {**$r, branch_totals:$bt}
$w = json($out) >> [self:write]{path:"outputs/vehicle_report.json"}
$dupids = $v >> [table:groupby]{by:"invoice_id"}
return {write:$w, total_actual:$r.total_actual, duplicates:$r.duplicates, missing_checks:$r.missing_checks, mismatches:$r.mismatches,
  unmatched:$r.unmatched, branch_totals:$bt, nrows:len($r.rows),
  dup_groups:$dupids.items >> [table:filter]{where:($g)=> $g.count > 1},
  mism:$r.rows >> [table:filter]{where:($x)=> abs($x.difference) > 500},
  sum_check:sum($bt >> [table:each]{return $it.actual_cost})}
